  ('LBN-2020-007', 'Article 12', 'حظر سقوط العقوبة بالتقادم لجرائم الإثراء غير المشروع', 'ar', 'Illicit Enrichment and Assets/Interests Declaration Law, Article Article 12', 'No Prescription', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-007', NULL, 'Replaced obsolete 1954 law. Expanded declaration requirements and removed prescription period. Assigned NACC as sole body for receiving declarations (previously 24 different bodies).', 'en', 'Illicit Enrichment and Assets/Interests Declaration Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2014-008', 'Article 2', 'Définition de la violence domestique: tout acte, omission ou menace par un membre de la famille', 'fr', 'Law on Protection of Women and Family Members from Domestic Violence, Article Article 2', 'Domestic Violence Definition', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2014-008', 'Article 2', 'تعريف العنف الأسري: أي فعل أو امتناع أو تهديد من أحد أفراد الأسرة', 'ar', 'Law on Protection of Women and Family Members from Domestic Violence, Article Article 2', 'Domestic Violence Definition', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2014-008', 'Article 3', 'Formes de violence: meurtre, dommage physique, psychologique, sexuel, économique', 'fr', 'Law on Protection of Women and Family Members from Domestic Violence, Article Article 3', 'Forms of Violence', 'Recent Legislation - Women''s Rights and Protection');
