  ('LBN-2010-010', 'Article 1-5', 'Création de l''Administration libanaise du pétrole (LPA) comme institution publique autonome', 'fr', 'Offshore Petroleum Resources Law (OPRL), Article Article 1-5', 'LPA Establishment', 'Recent Legislation - Energy and Petroleum'),
