  ('LBN-2010-010', 'Article 87', 'Création du fonds souverain de richesse pour les revenus pétroliers et gaziers', 'fr', 'Offshore Petroleum Resources Law (OPRL), Article Article 87', 'Sovereign Wealth Fund', 'Recent Legislation - Energy and Petroleum'),
