  ('LBN-2010-010', NULL, 'Established legal framework for offshore oil and gas exploration. Created Lebanese Petroleum Administration as independent regulator. Mandated creation of sovereign wealth fund for petroleum revenues.', 'en', 'Offshore Petroleum Resources Law (OPRL) — Historical Context', 'Historical context and overview', 'Recent Legislation - Energy and Petroleum'),
  ('LBN-2018-011', 'Article 1', 'Publication obligatoire des informations relatives aux activités pétrolières', 'fr', 'Law on Enhancing Transparency in the Petroleum Sector, Article Article 1', 'Mandatory Publication', 'Recent Legislation - Anti-Corruption and Transparency'),
