  ('LBN-2018-011', NULL, 'First sector-specific transparency law in Lebanon. Made Lebanon first Eastern Mediterranean country to publish oil contracts. Requires disclosure of beneficial ownership - a global benchmark.', 'en', 'Law on Enhancing Transparency in the Petroleum Sector — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2023-012', 'Article 1-3', 'Création du Fonds souverain libanais et de son conseil d''administration indépendant', 'fr', 'Lebanese Sovereign Wealth Fund Law, Article Article 1-3', 'Fund Establishment', 'Recent Legislation - Energy and Petroleum'),
  ('LBN-2023-012', 'Article 1-3', 'إنشاء الصندوق السيادي اللبناني ومجلس إدارته المستقل', 'ar', 'Lebanese Sovereign Wealth Fund Law, Article Article 1-3', 'Fund Establishment', 'Recent Legislation - Energy and Petroleum'),
  ('LBN-2023-012', 'Article 5', '80% des revenus du fonds pour l''épargne et l''investissement, 20% pour projets de développement local', 'fr', 'Lebanese Sovereign Wealth Fund Law, Article Article 5', 'Revenue Allocation', 'Recent Legislation - Energy and Petroleum'),
  ('LBN-2023-012', 'Article 5', '80% من إيرادات الصندوق للادخار والاستثمار، 20% للمشاريع التنموية المحلية', 'ar', 'Lebanese Sovereign Wealth Fund Law, Article Article 5', 'Revenue Allocation', 'Recent Legislation - Energy and Petroleum'),
