  ('LBN-2022-014', 'Article 150', 'Levée du secret bancaire pour les fonctionnaires, époux et enfants mineurs', 'fr', 'Banking Secrecy Law Amendment, Article Article 150', 'Public Officials Exemption', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2022-014', 'Article 150', 'رفع السرية المصرفية للمسؤولين العمومين وزوجاتهم وأولادهم القصر', 'ar', 'Banking Secrecy Law Amendment, Article Article 150', 'Public Officials Exemption', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2022-014', 'Article 7', 'Autorisation d''accès aux comptes rétroactivement jusqu''en 1988 dans les affaires de corruption', 'fr', 'Banking Secrecy Law Amendment, Article Article 7', 'Retroactive Access', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2022-014', 'Article 7', 'السماح للسلطات القضائية بالوصول للحسابات بأثر رجعي حتى عام 1988 في قضايا الفساد', 'ar', 'Banking Secrecy Law Amendment, Article Article 7', 'Retroactive Access', 'Recent Legislation - Banking Sector Reform'),
