  ('LBN-2022-014', NULL, 'First major amendment to 1956 Banking Secrecy Law. Passed under IMF pressure. Removed secrecy for public officials, allowed retroactive access for corruption investigations. Further amended in 2025.', 'en', 'Banking Secrecy Law Amendment — Historical Context', 'Historical context and overview', 'Recent Legislation - Banking Sector Reform');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-2025-015', 'Article 1', 'Octroi à la banque centrale, à la Commission de contrôle bancaire et au Fonds de garantie des dépôts du droit de lever le secret bancaire', 'fr', 'Banking Secrecy Law Amendment (Second), Article Article 1', 'Expanded Access Rights', 'Recent Legislation - Banking Sector Reform'),
