  ('LBN-2025-015', 'Article 2', 'Effet rétroactif de 10 ans pour auditer les ingénieries financières et transactions post-2019', 'fr', 'Banking Secrecy Law Amendment (Second), Article Article 2', '10-Year Retroactivity', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-015', 'Article 2', 'الأثر الرجعي لمدة 10 سنوات للتدقيق في الهندسات المالية ومعاملات ما بعد 2019', 'ar', 'Banking Secrecy Law Amendment (Second), Article Article 2', '10-Year Retroactivity', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-015', 'Article 3', 'Accès aux informations par nom et non seulement par numéro de compte pour audit et restructuration du secteur bancaire', 'fr', 'Banking Secrecy Law Amendment (Second), Article Article 3', 'Name-Based Access', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-015', 'Article 3', 'الوصول للمعلومات بالاسم وليس فقط برقم الحساب للتدقيق وإعادة هيكلة القطاع المصرفي', 'ar', 'Banking Secrecy Law Amendment (Second), Article Article 3', 'Name-Based Access', 'Recent Legislation - Banking Sector Reform'),
