  ('LBN-2025-016', 'Article 3-5', 'Création de la Haute Commission bancaire (HBC) à la Banque du Liban', 'fr', 'Bank Reform and Reorganization Law, Article Article 3-5', 'Higher Banking Commission', 'Recent Legislation - Banking Sector Reform'),
