  ('LBN-2025-016', 'Article 10-11', 'تعيين مقيّمين مستقلين لتقييم المصارف وفق المعايير الدولية', 'ar', 'Bank Reform and Reorganization Law, Article Article 10-11', 'Independent Valuation', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-016', 'Article 15-20', 'Pouvoirs de restructuration: augmentation capital, fusion, vente, liquidation', 'fr', 'Bank Reform and Reorganization Law, Article Article 15-20', 'Restructuring Powers', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-016', 'Article 15-20', 'صلاحيات إعادة الهيكلة: زيادة رأس المال، الدمج، البيع، التصفية', 'ar', 'Bank Reform and Reorganization Law, Article Article 15-20', 'Restructuring Powers', 'Recent Legislation - Banking Sector Reform'),
  ('LBN-2025-016', NULL, 'One of three key IMF prior actions. Establishes framework for bank restructuring six years into financial crisis. Gives BdL Governor significant powers. Criticized for banking lobby influence in HBC composition.', 'en', 'Bank Reform and Reorganization Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Banking Sector Reform'),
