  ('LBN-2020-017', 'Article 2', 'Restriction de liberté de mouvement pour nécessité absolue uniquement', 'fr', 'Decree Declaring State of General Mobilization to Counter Coronavirus Spread, Article Article 2', 'Movement Restrictions', 'Recent Legislation - Healthcare and Pandemic Response'),
