  ('LBN-2021-018', 'Article 2', 'إنشاء صندوق تعويض للإصابات المرتبطة بلقاح كوفيد-19', 'ar', 'Law Regulating Emergency Use of Medical Products to Combat COVID-19 Pandemic, Article Article 2', 'Compensation Fund', 'Recent Legislation - Healthcare and Pandemic Response'),
  ('LBN-2021-018', 'Article 3', 'Autorisation du secteur privé d''acheter vaccins avec licence du ministère de la Santé', 'fr', 'Law Regulating Emergency Use of Medical Products to Combat COVID-19 Pandemic, Article Article 3', 'Private Sector Procurement', 'Recent Legislation - Healthcare and Pandemic Response'),
