  ('LBN-2018-020', NULL, 'Complements Law 444/2002. Addresses air pollution from power plants, vehicles, generators. Aligns with Lebanon''s NDC targets for 2030.', 'en', 'Air Quality Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2002-021', 'Articles 1-10', 'Création de l''Autorité de régulation des télécommunications (TRA) comme autorité indépendante', 'fr', 'Telecommunications Sector Law, Article Articles 1-10', 'TRA Establishment', 'Recent Legislation - Telecommunications and Technology'),
