INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-2002-021', NULL, 'Passed in anticipation of Paris II donors conference. TRA board expired in 2012 and never reconstituted. Liban Telecom never established. Law remains largely unimplemented after 20+ years.', 'en', 'Telecommunications Sector Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Telecommunications and Technology'),
  ('LBN-2025-022', 'Articles on SJC', 'Expansion participation juges élections Conseil supérieur de la magistrature - 5 membres élus par juges', 'fr', 'Law Regulating the Ordinary Judiciary, Article Articles on SJC', 'SJC Elections', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Articles on SJC', 'توسيع مشاركة القضاة في انتخابات المجلس الأعلى للقضاء - 5 أعضاء منتخبون من القضاة', 'ar', 'Law Regulating the Ordinary Judiciary, Article Articles on SJC', 'SJC Elections', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article on Independence', 'Renforcement indépendance judiciaire et droits juges liberté d''expression', 'fr', 'Law Regulating the Ordinary Judiciary, Article Article on Independence', 'Judicial Independence', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article on Independence', 'تعزيز استقلال القضاء وحقوق القضاة في حرية التعبير', 'ar', 'Law Regulating the Ordinary Judiciary, Article Article on Independence', 'Judicial Independence', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article on Terms', 'Mandats de 4 ans pour postes judiciaires', 'fr', 'Law Regulating the Ordinary Judiciary, Article Article on Terms', 'Judicial Terms', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article on Terms', 'مدد ولاية مدتها 4 سنوات للمناصب القضائية', 'ar', 'Law Regulating the Ordinary Judiciary, Article Article on Terms', 'Judicial Terms', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article 42', 'Pouvoir du procureur général de demander arrêt des poursuites (controversé)', 'fr', 'Law Regulating the Ordinary Judiciary, Article Article 42', 'Prosecution Powers', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', 'Article 42', 'سلطة النائب العام في طلب وقف الدعاوى (مثير للجدل)', 'ar', 'Law Regulating the Ordinary Judiciary, Article Article 42', 'Prosecution Powers', 'Recent Legislation - Judicial Reform'),
  ('LBN-2025-022', NULL, 'First major judicial reform since independence. Based on draft from 2018 by coalition of legal NGOs. Criticized by HRW and Venice Commission for not fully meeting international standards. Enters force January 2026.', 'en', 'Law Regulating the Ordinary Judiciary — Historical Context', 'Historical context and overview', 'Recent Legislation - Judicial Reform'),
  ('LBN-2000-023', 'Article 26', 'L''employeur ne peut pas discriminer entre travailleurs et travailleuses dans type travail, montant salaire, emploi, promotion, qualification professionnelle, vêtements', 'fr', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 26', 'Gender Non-Discrimination', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', 'Article 26', 'يجوز لصاحب العمل أن يميز بين العاملين والعاملات في نوع العمل ومقدار الأجر أو الراتب والتوظيف والترقية والتأهيل المهني واللباس', 'ar', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 26', 'Gender Non-Discrimination', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', 'Article 27', 'Maintien Article 27 interdisant travail femmes dans certaines industries (liste annexée)', 'fr', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 27', 'Women''s Employment Restrictions', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', 'Article 27', 'استمرار المادة 27 التي تحظر عمل النساء في بعض الصناعات (قائمة مرفقة)', 'ar', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 27', 'Women''s Employment Restrictions', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', 'Article 28', 'Congé maternité 7 semaines secteur privé', 'fr', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 28', 'Maternity Leave', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', 'Article 28', 'إجازة الأمومة 7 أسابيع في القطاع الخاص', 'ar', 'Labor Law Article 26 Amendment - Gender Non-Discrimination, Article Article 28', 'Maternity Leave', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2000-023', NULL, 'First amendment prohibiting gender discrimination in Labor Law. However, Article 27 restrictions on women''s work in certain industries remained. Maternity leave extended to 60 days (public sector) and 7 weeks (private sector).', 'en', 'Labor Law Article 26 Amendment - Gender Non-Discrimination — Historical Context', 'Historical context and overview', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2025-024', 'Article 1', 'Nouvelle définition employeur: ''patron'' au lieu de ''maître de travail''', 'fr', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 1', 'Employer Definition', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', 'Article 1', 'تعريف جديد لصاحب العمل: صاحب العمل بدلاً من رب العمل', 'ar', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 1', 'Employer Definition', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', 'Article 2', 'Reconnaissance officielle du travail à distance pour première fois', 'fr', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 2', 'Remote Work Recognition', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', 'Article 2', 'الاعتراف الرسمي بالعمل عن بُعد لأول مرة', 'ar', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 2', 'Remote Work Recognition', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', 'Article 12', 'Cadre complet formes travail non traditionnel: compressé, à temps partiel, saisonnier, à distance', 'fr', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 12', 'Non-Traditional Work Forms', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', 'Article 12', 'إطار شامل لأشكال العمل غير التقليدي: المضغوط، الجزئي، الموسمي، عن بُعد', 'ar', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work, Article Article 12', 'Non-Traditional Work Forms', 'Recent Legislation - Labor and Employment'),
  ('LBN-2025-024', NULL, 'First major labor law reform in decades. Recognizes remote work, part-time employment, compressed schedules, and seasonal work. Brings Lebanese labor law closer to international standards.', 'en', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work — Historical Context', 'Historical context and overview', 'Recent Legislation - Labor and Employment'),
  ('LBN-2021-025', 'Article 7', 'Interdiction accords anti-concurrentiels: fixation prix, partage marchés, manipulation appels d''offres', 'fr', 'Competition Law, Article Article 7', 'Anti-Competitive Agreements', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 7', 'حظر الاتفاقات المناهضة للمنافسة: التثبيت السعري، تقسيم الأسواق، التلاعب بالمناقصات', 'ar', 'Competition Law, Article Article 7', 'Anti-Competitive Agreements', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 9', 'Définition position dominante (35% part marché individuelle, 45-55% collective) et abus', 'fr', 'Competition Law, Article Article 9', 'Abuse of Dominant Position', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 9', 'تعريف الموقف المهيمن (35% حصة سوق فردية، 45-55% جماعية) وإساءة استخدامه', 'ar', 'Competition Law, Article Article 9', 'Abuse of Dominant Position', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 14', 'Contrôle des fusions: obligation approbation pour fusions dépassant 30% part marché', 'fr', 'Competition Law, Article Article 14', 'Merger Control', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 14', 'الرقابة على الاندماجات: إلزامية الموافقة للاندماجات التي تتجاوز 30% من الحصة السوقية', 'ar', 'Competition Law, Article Article 14', 'Merger Control', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 22', 'Sanctions: amendes jusqu''à 10% du revenu annuel', 'fr', 'Competition Law, Article Article 22', 'Penalties', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', 'Article 22', 'العقوبات: غرامات تصل إلى 10% من الدخل السنوي', 'ar', 'Competition Law, Article Article 22', 'Penalties', 'Recent Legislation - Economic Reform'),
  ('LBN-2021-025', NULL, 'First comprehensive competition law in Lebanon. Establishes National Competition Authority (not yet created). Addresses cartels, abuse of dominance, and merger control. Critical for economic recovery and reducing inequality.', 'en', 'Competition Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Economic Reform'),
  ('LBN-2019-026', 'N/A', 'Interdiction retrait USD ou transfert à l''étranger pour dépôts ouverts avant 17 octobre 2019', 'fr', 'Informal Capital Controls - No Formal Law, Article N/A', 'Withdrawal Restrictions', 'Recent Legislation - Capital Controls and Banking Restrictions'),
  ('LBN-2019-026', 'N/A', 'حظر السحب بالدولار الأمريكي أو تحويله إلى الخارج للودائع المفتوحة قبل 17 أكتوبر 2019', 'ar', 'Informal Capital Controls - No Formal Law, Article N/A', 'Withdrawal Restrictions', 'Recent Legislation - Capital Controls and Banking Restrictions'),
  ('LBN-2019-026', 'N/A', 'Autorisation transferts depuis comptes ''fresh dollars'' (ouverts après octobre 2019)', 'fr', 'Informal Capital Controls - No Formal Law, Article N/A', 'Fresh Dollar Exception', 'Recent Legislation - Capital Controls and Banking Restrictions'),
  ('LBN-2019-026', 'N/A', 'السماح بالتحويلات من حسابات ''الدولار الطازج'' (فتحت بعد أكتوبر 2019)', 'ar', 'Informal Capital Controls - No Formal Law, Article N/A', 'Fresh Dollar Exception', 'Recent Legislation - Capital Controls and Banking Restrictions'),
  ('LBN-2019-026', NULL, 'Banks imposed informal capital controls on October 18, 2019 following bank run. No parliamentary legislation passed despite IMF requirements. Multiple draft laws debated but never enacted as of April 2025.', 'en', 'Informal Capital Controls - No Formal Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Capital Controls and Banking Restrictions'),
  ('LBN-2020-027', 'Outcome 1', 'Achèvement et activation législations spécialisées lutte corruption', 'fr', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 1', 'Legislative Framework', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 1', 'إكمال وتفعيل التشريعات المتخصصة لمكافحة الفساد', 'ar', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 1', 'Legislative Framework', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 2-3', 'Renforcement intégrité fonction publique et marchés publics', 'fr', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 2-3', 'Public Sector Integrity', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 2-3', 'تعزيز النزاهة في الوظيفة العامة والمشتريات العامة', 'ar', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 2-3', 'Public Sector Integrity', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 4-5', 'Renforcement intégrité systèmes judiciaire et de contrôle', 'fr', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 4-5', 'Judicial and Oversight Systems', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 4-5', 'تعزيز النزاهة في النظامين القضائي والرقابي', 'ar', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 4-5', 'Judicial and Oversight Systems', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 6', 'Engagement composantes société libanaise promotion culture intégrité', 'fr', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 6', 'Cultural Change', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', 'Outcome 6', 'إشراك جميع مكونات المجتمع اللبناني في تعزيز ثقافة النزاهة', 'ar', 'National Anti-Corruption Strategy 2020-2025, Article Outcome 6', 'Cultural Change', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-027', NULL, 'Comprehensive roadmap for anti-corruption efforts. Developed with UNDP/UNODC support. Approved by Ministerial Anti-Corruption Committee. Implementation remains limited due to political and economic crises.', 'en', 'National Anti-Corruption Strategy 2020-2025 — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2025-028', 'Article (Draft)', 'Remboursement dépôts jusqu''à 100,000 USD en 4 ans pour petits déposants (85% des déposants)', 'fr', 'Draft Financial Gap Law (Gap Law), Article Article (Draft)', 'Small Depositor Protection', 'Recent Legislation - Economic and Financial Crisis'),
  ('LBN-2025-028', 'Article (Draft)', 'رد الودائع حتى 100,000 دولار خلال 4 سنوات للمودعين الصغار (85% من المودعين)', 'ar', 'Draft Financial Gap Law (Gap Law), Article Article (Draft)', 'Small Depositor Protection', 'Recent Legislation - Economic and Financial Crisis'),
