INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-2025-028', 'Article (Draft)', 'تعويض المودعين الكبار بأوراق مالية مضمونة بالأصول', 'ar', 'Draft Financial Gap Law (Gap Law), Article Article (Draft)', 'Large Depositor Compensation', 'Recent Legislation - Economic and Financial Crisis'),
