  ('LBN-2002-029', 'Article 1-5', 'Création Autorité régulation électricité (ERA) comme autorité indépendante', 'fr', 'Electricity Sector Regulation Law, Article Article 1-5', 'ERA Establishment', 'Recent Legislation - Energy and Infrastructure'),
  ('LBN-2002-029', 'Article 1-5', 'إنشاء هيئة تنظيم قطاع الكهرباء (ERA) كهيئة مستقلة', 'ar', 'Electricity Sector Regulation Law, Article Article 1-5', 'ERA Establishment', 'Recent Legislation - Energy and Infrastructure'),
  ('LBN-2002-029', 'Article 12', 'Droit public accès information et participation élaboration politiques', 'fr', 'Electricity Sector Regulation Law, Article Article 12', 'Transparency and Participation', 'Recent Legislation - Energy and Infrastructure'),
