  ('LBN-2002-029', 'Article 16-18', 'Licences production, transport, distribution électricité', 'fr', 'Electricity Sector Regulation Law, Article Article 16-18', 'Licensing Framework', 'Recent Legislation - Energy and Infrastructure'),
  ('LBN-2002-029', 'Article 16-18', 'تراخيص إنتاج ونقل وتوزيع الكهرباء', 'ar', 'Electricity Sector Regulation Law, Article Article 16-18', 'Licensing Framework', 'Recent Legislation - Energy and Infrastructure'),
  ('LBN-2002-029', NULL, 'Passed before Paris II conference. Electricity Regulatory Authority never established. Law remains largely unimplemented. Electricité du Liban (EdL) continues as state monopoly with massive deficits.', 'en', 'Electricity Sector Regulation Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Energy and Infrastructure'),
  ('LBN-2017-030', 'Article 1', 'Réductions douanières produits environnementaux et équipements énergies renouvelables et efficacité énergétique', 'fr', 'Tax Incentives on Environmental Products and Services Decree, Article Article 1', 'Customs Reductions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2017-030', 'Article 1', 'تخفيضات جمركية على المنتجات البيئية والمعدات المتعلقة بالطاقة المتجددة وكفاءة الطاقة', 'ar', 'Tax Incentives on Environmental Products and Services Decree, Article Article 1', 'Customs Reductions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2017-030', 'Article 2', 'Exonérations fiscales entreprises réalisant projets environnementaux incluant projets climat', 'fr', 'Tax Incentives on Environmental Products and Services Decree, Article Article 2', 'Tax Breaks', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2017-030', 'Article 2', 'إعفاءات ضريبية للشركات التي تقوم بمشاريع بيئية بما فيها مشاريع المناخ', 'ar', 'Tax Incentives on Environmental Products and Services Decree, Article Article 2', 'Tax Breaks', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2017-030', NULL, 'Part of Lebanon''s climate mitigation strategy. Encourages deployment of climate-friendly technologies. Complements vehicle tax reductions for hybrid/electric cars in budget laws.', 'en', 'Tax Incentives on Environmental Products and Services Decree — Historical Context', 'Historical context and overview', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 1', 'Limites émission polluants centrales production énergie (ozone, monoxyde carbone, particules)', 'fr', 'Emission Limit Values for Air Pollutants Decision, Article Article 1', 'Power Plant Emissions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 1', 'حدود انبعاث الملوثات من محطات توليد الطاقة (الأوزون، أول أكسيد الكربون، الجسيمات)', 'ar', 'Emission Limit Values for Air Pollutants Decision, Article Article 1', 'Power Plant Emissions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 2', 'Limites émission groupes électrogènes privés', 'fr', 'Emission Limit Values for Air Pollutants Decision, Article Article 2', 'Private Generator Emissions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 2', 'حدود انبعاث المولدات الخاصة', 'ar', 'Emission Limit Values for Air Pollutants Decision, Article Article 2', 'Private Generator Emissions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 3', 'Normes qualité carburant', 'fr', 'Emission Limit Values for Air Pollutants Decision, Article Article 3', 'Fuel Quality Standards', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', 'Article 3', 'معايير جودة الوقود', 'ar', 'Emission Limit Values for Air Pollutants Decision, Article Article 3', 'Fuel Quality Standards', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2022-031', NULL, 'Implements Lebanon''s NDC commitments. Limits emissions from major pollution sources. Addresses severe air quality problems in Lebanon, especially from private generators during electricity crisis.', 'en', 'Emission Limit Values for Air Pollutants Decision — Historical Context', 'Historical context and overview', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2008-032', 'Single Article', 'Approbation adhésion Liban Convention ONU lutte corruption adoptée par Assemblée générale résolution 58/4', 'fr', 'Law Approving Lebanon''s Accession to UN Convention Against Corruption (UNCAC), Article Single Article', 'UNCAC Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2008-032', 'Single Article', 'الموافقة على انضمام لبنان إلى اتفاقية الأمم المتحدة لمكافحة الفساد المعتمدة من الجمعية العامة في قرارها 58/4', 'ar', 'Law Approving Lebanon''s Accession to UN Convention Against Corruption (UNCAC), Article Single Article', 'UNCAC Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2008-032', NULL, 'Lebanon ratified UNCAC in 2008. Led to subsequent anti-corruption legislation including Whistleblower Protection Law (2018), Access to Information Law (2017), and National Anti-Corruption Commission Law (2020).', 'en', 'Law Approving Lebanon''s Accession to UN Convention Against Corruption (UNCAC) — Historical Context', 'Historical context and overview', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2022-033', 'Single Article', 'Ratification Convention droits personnes handicapées et Protocole facultatif', 'fr', 'Law Ratifying Convention on Rights of Persons with Disabilities and Optional Protocol, Article Single Article', 'CRPD Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2022-033', 'Single Article', 'التصديق على اتفاقية حقوق الأشخاص ذوي الإعاقة والملحق الاختياري', 'ar', 'Law Ratifying Convention on Rights of Persons with Disabilities and Optional Protocol, Article Single Article', 'CRPD Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2022-033', NULL, 'Lebanon signed CRPD in 2007 but ratification took 15 years. Law 220/2000 (Disability Rights) preceded the UN Convention. Ratification strengthens legal framework for disability rights in Lebanon.', 'en', 'Law Ratifying Convention on Rights of Persons with Disabilities and Optional Protocol — Historical Context', 'Historical context and overview', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2020-034', 'Article 1', 'Renforcement peines violence économique et psychologique', 'fr', 'Amendment to Domestic Violence Protection Law, Article Article 1', 'Economic/Psychological Violence', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2020-034', 'Article 1', 'تعزيز العقوبات على العنف الاقتصادي والنفسي', 'ar', 'Amendment to Domestic Violence Protection Law, Article Article 1', 'Economic/Psychological Violence', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2020-034', 'Article 2', 'Criminalisation nouvelles formes harcèlement', 'fr', 'Amendment to Domestic Violence Protection Law, Article Article 2', 'Harassment', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2020-034', 'Article 2', 'تجريم أشكال جديدة من التحرش', 'ar', 'Amendment to Domestic Violence Protection Law, Article Article 2', 'Harassment', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2020-034', NULL, 'Amended Law 293/2014 to address gaps identified in implementation. Strengthened penalties for non-physical forms of violence. Still does not criminalize marital rape.', 'en', 'Amendment to Domestic Violence Protection Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Women''s Rights and Protection'),
  ('LBN-2021-035', 'Article 1', 'Suppression condition justification qualité ou intérêt pour obtenir informations', 'fr', 'Amendment to Access to Information Law, Article Article 1', 'No Capacity Requirement', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', 'Article 1', 'إزالة شرط إثبات الصفة أو المصلحة للحصول على المعلومات', 'ar', 'Amendment to Access to Information Law, Article Article 1', 'No Capacity Requirement', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', 'Article 2', 'Inclusion juridictions religieuses dans champ d''application loi', 'fr', 'Amendment to Access to Information Law, Article Article 2', 'Religious Courts', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', 'Article 2', 'إدراج المحاكم الشرعية ضمن نطاق القانون', 'ar', 'Amendment to Access to Information Law, Article Article 2', 'Religious Courts', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', 'Article 3', 'Obligation répondre demandes informations et non-renvoi autres instances', 'fr', 'Amendment to Access to Information Law, Article Article 3', 'Mandatory Response', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', 'Article 3', 'الإلزام بالرد على طلبات المعلومات وعدم الإحالة لجهات أخرى', 'ar', 'Amendment to Access to Information Law, Article Article 3', 'Mandatory Response', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-035', NULL, 'Strengthened Law 28/2017 based on civil society advocacy. Removed barriers to accessing information. Included religious courts previously exempted.', 'en', 'Amendment to Access to Information Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-036', 'Article 1', 'Mécanismes récupération fonds détournés et restitution État', 'fr', 'Asset Recovery Law, Article Article 1', 'Asset Recovery Mechanisms', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-036', 'Article 1', 'آليات استرداد الأموال المنهوبة وإعادتها للدولة', 'ar', 'Asset Recovery Law, Article Article 1', 'Asset Recovery Mechanisms', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-036', 'Article 2', 'Coopération internationale récupération fonds', 'fr', 'Asset Recovery Law, Article Article 2', 'International Cooperation', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-036', 'Article 2', 'التعاون الدولي في استرداد الأموال', 'ar', 'Asset Recovery Law, Article Article 2', 'International Cooperation', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2021-036', NULL, 'Complements Law 175/2020 and Law 189/2020. Implements UNCAC provisions on asset recovery. Provides framework for recovering stolen assets from abroad.', 'en', 'Asset Recovery Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-037', 'Article 9 (Amended)', 'Possibilité soumettre dénonciations au parquet en plus Commission nationale anti-corruption', 'fr', 'Amendment to Whistleblower Protection Law, Article Article 9 (Amended)', 'Public Prosecution Access', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-037', 'Article 9 (Amended)', 'إمكانية تقديم البلاغات للنيابة العامة بالإضافة للهيئة الوطنية لمكافحة الفساد', 'ar', 'Amendment to Whistleblower Protection Law, Article Article 9 (Amended)', 'Public Prosecution Access', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-2020-037', NULL, 'Amended Law 83/2018 to allow Public Prosecution to receive whistleblower complaints alongside NACC. Created Whistleblowers Reception Office at Ministry of Justice.', 'en', 'Amendment to Whistleblower Protection Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Anti-Corruption and Transparency'),
  ('LBN-1977-038', 'Article 16', 'Application dispositions loi élections législatives aux élections municipales', 'fr', 'Municipalities Law, Article Article 16', 'Parliamentary Election Provisions Apply', 'Recent Legislation - Electoral Reform');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-1977-038', 'Article 16', 'تطبيق أحكام قانون الانتخابات النيابية على الانتخابات البلدية', 'ar', 'Municipalities Law, Article Article 16', 'Parliamentary Election Provisions Apply', 'Recent Legislation - Electoral Reform'),
  ('LBN-1977-038', NULL, 'Passed at end of 1975-1977 civil war. Municipal elections still use majoritarian system (Law 25/2008) unlike parliamentary elections which use proportional representation (Law 44/2017). Proposed reforms in 2023 would introduce proportional representation for municipal elections.', 'en', 'Municipalities Law — Historical Context', 'Historical context and overview', 'Recent Legislation - Electoral Reform'),
  ('LBN-2013-039', 'Article 1', 'Cadre secteur privé rapport émissions gaz effet serre sur base volontaire', 'fr', 'Carbon Reporting Mechanism Decision, Article Article 1', 'Voluntary Reporting', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2013-039', 'Article 1', 'إطار للقطاع الخاص للإبلاغ عن انبعاثات الغازات الدفيئة على أساس طوعي', 'ar', 'Carbon Reporting Mechanism Decision, Article Article 1', 'Voluntary Reporting', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2013-039', 'Article 2', 'Attribution certificat rapport ministère Environnement', 'fr', 'Carbon Reporting Mechanism Decision, Article Article 2', 'Reporting Certificate', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2013-039', 'Article 2', 'منح شهادة إبلاغ من وزارة البيئة', 'ar', 'Carbon Reporting Mechanism Decision, Article Article 2', 'Reporting Certificate', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2013-039', NULL, 'Early climate action measure. Voluntary carbon reporting for private sector. Part of Lebanon''s climate mitigation strategy and NDC implementation.', 'en', 'Carbon Reporting Mechanism Decision — Historical Context', 'Historical context and overview', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2018-040', 'Article 55', 'Exonération douanière et fiscale véhicules hybrides et électriques', 'fr', 'Budget Law 79/2018 Article 55 - Vehicle Tax Reduction for Hybrid/Electric Vehicles, Article Article 55', 'Tax Exemptions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2018-040', 'Article 55', 'إعفاء جمركي وضريبي للمركبات الهجينة والكهربائية', 'ar', 'Budget Law 79/2018 Article 55 - Vehicle Tax Reduction for Hybrid/Electric Vehicles, Article Article 55', 'Tax Exemptions', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2018-040', NULL, 'Incentivizes low-emission vehicles. Maintained through 2019-2022 despite economic crisis. Extended by Budget Law 10/2022.', 'en', 'Budget Law 79/2018 Article 55 - Vehicle Tax Reduction for Hybrid/Electric Vehicles — Historical Context', 'Historical context and overview', 'Recent Legislation - Environmental and Climate'),
  ('LBN-2007-041', 'Single Article', 'Ratification Convention New York 1958', 'fr', 'Law Ratifying New York Convention 1958, Article Single Article', 'New York Convention Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2007-041', 'Single Article', 'التصديق على اتفاقية نيويورك 1958', 'ar', 'Law Ratifying New York Convention 1958, Article Single Article', 'New York Convention Ratification', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-2007-041', NULL, 'Lebanon ratified New York Convention on Recognition and Enforcement of Foreign Arbitral Awards. Important for international trade and investment disputes.', 'en', 'Law Ratifying New York Convention 1958 — Historical Context', 'Historical context and overview', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-ICSID', 'N/A', 'Acceptation arbitrage international différends investissement', 'fr', 'Lebanon ICSID Convention Member, Article N/A', 'Investment Arbitration', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-ICSID', 'N/A', 'قبول التحكيم الدولي في منازعات الاستثمار', 'ar', 'Lebanon ICSID Convention Member, Article N/A', 'Investment Arbitration', 'Recent Legislation - International Treaty Ratifications'),
  ('LBN-ICSID', NULL, 'Lebanon member of ICSID Convention since 1971. Government accepts international arbitration for investment disputes, especially with countries having investment protection agreements.', 'en', 'Lebanon ICSID Convention Member — Historical Context', 'Historical context and overview', 'Recent Legislation - International Treaty Ratifications'),
  ('LB-TAX-001', '1-15', 'Tax on profits from industrial, commercial, and non-commercial professions. Schedular system: profits from trade/industry, profits from professions, salaries/wages, movable capital income.', 'en', 'Income Tax Law, Article 1-15', 'Tax categories', 'Tax & Fiscal'),
  ('LB-TAX-001', '31-45', 'Tax on salaries, wages, and pensions. Employer withholding obligations.', 'en', 'Income Tax Law, Article 31-45', 'Salary tax', 'Tax & Fiscal'),
  ('LB-TAX-001', '51-65', 'Tax on income from movable capital: interest, dividends, investment returns.', 'en', 'Income Tax Law, Article 51-65', 'Capital income tax', 'Tax & Fiscal'),
  ('LB-TAX-001', NULL, 'Lebanon''s income tax system is a schedular (cedular) system where different types of income are taxed separately rather than aggregated. There is no unified personal income tax. Tax rates are relatively low compared to regional and international averages, reflecting Lebanon''s traditionally liberal economic model. The system has been criticized for its regressive nature and weak enforcement.', 'en', 'Income Tax Law — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-001', '7.8', 'Authorized banks to set aside provisions for doubtful debts.', 'en', 'Income Tax Law — Amendment: Decree-Law No. 83/1977', 'Amendment', 'Tax & Fiscal'),
  ('LB-TAX-001', NULL, 'Tax rates and brackets have been modified through annual budget laws.', 'en', 'Income Tax Law — Amendment: Various budget laws', 'Amendment', 'Tax & Fiscal'),
  ('LB-TAX-001', NULL, 'Unified and simplified tax procedures.', 'en', 'Income Tax Law — Amendment: Law No. 44/2008 (Tax Procedures)', 'Amendment', 'Tax & Fiscal'),
  ('LB-TAX-002', '1-5', 'Scope: VAT applies to supply of goods and services in Lebanon, and importation of goods. Standard rate: 11%.', 'en', 'Value Added Tax (VAT) Law, Article 1-5', 'Scope and rate', 'Tax & Fiscal'),
  ('LB-TAX-002', NULL, 'Introduced in 2002 at a rate of 10%, later increased to 11%. Replaced the consumption tax system. Registration threshold applies for businesses with turnover above a set threshold. Exemptions include financial services, education, and certain basic food items. Administration by the VAT Directorate within the Ministry of Finance.', 'en', 'Value Added Tax (VAT) Law — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-002', NULL, 'Unified tax procedures law.', 'en', 'Value Added Tax (VAT) Law — Amendment: Law No. 44/2008', 'Amendment', 'Tax & Fiscal'),
  ('LB-TAX-002', NULL, 'VAT rate increased from 10% to 11% via Law No. 64/2017 (2017 budget).', 'en', 'Value Added Tax (VAT) Law — Amendment: Various budget laws (rate adjustments)', 'Amendment', 'Tax & Fiscal'),
  ('LB-TAX-003', NULL, 'Imposes stamp duty on various legal documents, contracts, receipts, and official papers. Rates vary by document type. A significant source of government revenue and a common feature of Lebanese administrative processes.', 'en', 'Stamp Duty / Fiscal Stamps Law — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-004', NULL, 'Governs customs duties, import/export procedures, transit goods, customs zones, and enforcement. Lebanon has been in accession negotiations with the WTO and has bilateral trade agreements affecting customs rates. Customs revenue has historically been a major source of government income.', 'en', 'Customs Code — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-005', NULL, 'Unified and simplified tax procedures across income tax, VAT, and other fiscal obligations. Implementing decree No. 2488 of July 3, 2009. Streamlined tax filing, assessment, objection, and collection procedures.', 'en', 'Tax Procedures Law (Unified) — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-006', NULL, 'Taxes on built property (buildings and structures). Calculated based on estimated rental value. One of the oldest existing tax instruments in Lebanon.', 'en', 'Built Property Tax — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-007', NULL, 'Enacted to comply with international standards on tax transparency (OECD/Global Forum). Allows exchange of tax-related information with treaty partner countries. Significant in the context of Lebanon''s banking secrecy tradition.', 'en', 'Exchange of Tax Information Law — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LB-TAX-008', NULL, 'Annual budget laws authorize government spending and often contain tax rate modifications. Lebanon notably failed to pass a budget from 2005 to 2017 (12 years), operating on extended twelve-monthly budgets. A budget was finally passed in 2017 (Law No. 64/2017), followed by the 2018 and 2019 budgets. Budget laws often include fiscal provisions that amend tax rates and thresholds.', 'en', 'Annual Budget Laws — Historical Context', 'Historical context and overview', 'Tax & Fiscal'),
  ('LBN-TAX-001', 'Article 4', 'Defines entities subject to tax including corporations, LLCs, branches of foreign companies, and any entity generating income from activities', 'en', 'Income Tax Law, Article Article 4', 'Scope of Coverage', 'Tax Law'),
  ('LBN-TAX-001', 'Article 4', 'Définition des entités assujetties à l''impôt', 'fr', 'Income Tax Law, Article Article 4', 'Scope of Coverage', 'Tax Law'),
  ('LBN-TAX-001', 'Article 4', 'تحديد الكيانات الخاضعة لأحكام الضريبة', 'ar', 'Income Tax Law, Article Article 4', 'Scope of Coverage', 'Tax Law'),
  ('LBN-TAX-001', 'Article 5', 'All net profits derived in Lebanon are subject to tax provisions - territorial principle', 'en', 'Income Tax Law, Article Article 5', 'Taxable Base', 'Tax Law'),
  ('LBN-TAX-001', 'Article 5', 'Tous les bénéfices nets réalisés au Liban sont soumis aux dispositions fiscales', 'fr', 'Income Tax Law, Article Article 5', 'Taxable Base', 'Tax Law'),
  ('LBN-TAX-001', 'Article 5', 'تخضع جميع الأرباح الصافية المتحققة في لبنان لأحكام الضريبة', 'ar', 'Income Tax Law, Article Article 5', 'Taxable Base', 'Tax Law'),
  ('LBN-TAX-001', 'Article 7', 'Defines deductible expenses (customary business expenses) and non-deductible expenses (interest on capital, personal expenses, foreign taxes)', 'en', 'Income Tax Law, Article Article 7', 'Deductible Expenses', 'Tax Law'),
  ('LBN-TAX-001', 'Article 7', 'Définition des dépenses déductibles et non déductibles', 'fr', 'Income Tax Law, Article Article 7', 'Deductible Expenses', 'Tax Law'),
  ('LBN-TAX-001', 'Article 7', 'تحديد المصاريف المسموح خصمها وغير المسموح بها', 'ar', 'Income Tax Law, Article Article 7', 'Deductible Expenses', 'Tax Law'),
  ('LBN-TAX-001', 'Article 63', 'Tax on interest and revenues from savings accounts, bank deposits, bonds - currently 7%', 'en', 'Income Tax Law, Article Article 63', 'Interest Taxation', 'Tax Law'),
  ('LBN-TAX-001', 'Article 63', 'Impôt sur les intérêts et revenus des comptes d''épargne', 'fr', 'Income Tax Law, Article Article 63', 'Interest Taxation', 'Tax Law'),
  ('LBN-TAX-001', 'Article 63', 'الضريبة على الفوائد والإيرادات من حسابات التوفير', 'ar', 'Income Tax Law, Article Article 63', 'Interest Taxation', 'Tax Law'),
  ('LBN-TAX-001', NULL, 'The Income Tax Law of 1959 is the foundational legislation for taxation in Lebanon. It established the territorial principle of taxation and the schedular system (three categories of income). The law has undergone numerous amendments, particularly in recent years (2017, 2019, 2022, 2024) to adapt to economic changes and increase revenue collection.', 'en', 'Income Tax Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-002', 'Article 2', 'Defines taxable transactions including supply of goods and services', 'en', 'Value Added Tax Law, Article Article 2', 'Taxable Transactions', 'Tax Law'),
  ('LBN-TAX-002', 'Article 2', 'Opérations imposables', 'fr', 'Value Added Tax Law, Article Article 2', 'Taxable Transactions', 'Tax Law'),
  ('LBN-TAX-002', 'Article 2', 'العمليات الخاضعة للضريبة', 'ar', 'Value Added Tax Law, Article Article 2', 'Taxable Transactions', 'Tax Law'),
  ('LBN-TAX-002', 'Article 16', 'Lists exempted activities including banking, financial services, insurance, and nurseries', 'en', 'Value Added Tax Law, Article Article 16', 'Exemptions', 'Tax Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-TAX-002', 'Article 16', 'Activités et biens exemptés', 'fr', 'Value Added Tax Law, Article Article 16', 'Exemptions', 'Tax Law'),
  ('LBN-TAX-002', 'Article 16', 'الأنشطة والسلع المعفاة', 'ar', 'Value Added Tax Law, Article Article 16', 'Exemptions', 'Tax Law'),
  ('LBN-TAX-002', 'Article 19', 'Exports and like transactions are zero-rated', 'en', 'Value Added Tax Law, Article Article 19', 'Export Exemption', 'Tax Law'),
  ('LBN-TAX-002', 'Article 19', 'Exemption des exportations et opérations similaires', 'fr', 'Value Added Tax Law, Article Article 19', 'Export Exemption', 'Tax Law'),
  ('LBN-TAX-002', 'Article 19', 'إعفاء الصادرات والعمليات المماثلة', 'ar', 'Value Added Tax Law, Article Article 19', 'Export Exemption', 'Tax Law'),
  ('LBN-TAX-002', 'Article 25', 'Standard VAT rate is 11%', 'en', 'Value Added Tax Law, Article Article 25', 'Tax Rate', 'Tax Law'),
  ('LBN-TAX-002', 'Article 25', 'Le taux de taxe est de 11%', 'fr', 'Value Added Tax Law, Article Article 25', 'Tax Rate', 'Tax Law'),
  ('LBN-TAX-002', 'Article 25', 'معدل الضريبة 11%', 'ar', 'Value Added Tax Law, Article Article 25', 'Tax Rate', 'Tax Law'),
  ('LBN-TAX-002', 'Article 35', 'Registration required for turnover exceeding LBP 500 million; quarterly filing by 20th of following month', 'en', 'Value Added Tax Law, Article Article 35', 'Registration and Filing', 'Tax Law'),
  ('LBN-TAX-002', 'Article 35', 'Enregistrement et déclarations périodiques', 'fr', 'Value Added Tax Law, Article Article 35', 'Registration and Filing', 'Tax Law'),
  ('LBN-TAX-002', 'Article 35', 'التسجيل والإقرارات الدورية', 'ar', 'Value Added Tax Law, Article Article 35', 'Registration and Filing', 'Tax Law'),
  ('LBN-TAX-002', NULL, 'VAT was introduced in Lebanon on 1 February 2002, replacing the previous turnover tax system. The law was designed to modernize the tax system and broaden the tax base. The standard rate of 11% is relatively low compared to international standards.', 'en', 'Value Added Tax Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-003', 'General Provisions', 'Annual progressive tax on built property ranging from 4% to 14% of net rental proceeds', 'en', 'Built Property Tax Decree, Article General Provisions', 'Tax Overview', 'Tax Law'),
  ('LBN-TAX-003', 'General Provisions', 'Taxe annuelle progressive sur les propriétés bâties', 'fr', 'Built Property Tax Decree, Article General Provisions', 'Tax Overview', 'Tax Law'),
  ('LBN-TAX-003', 'General Provisions', 'ضريبة سنوية تصاعدية على الأملاك المبنية', 'ar', 'Built Property Tax Decree, Article General Provisions', 'Tax Overview', 'Tax Law'),
  ('LBN-TAX-003', NULL, 'The Built Property Tax is one of Lebanon''s oldest property taxes, applying to rental income from built properties. The progressive rate structure aims to tax higher rental incomes at higher rates.', 'en', 'Built Property Tax Decree — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-004', 'Article 1-5', 'Taxable assets include all movable and immovable assets situated in Lebanon, regardless of inheritor''s residence', 'en', 'Legislative Decree on Inheritance and Gift Tax, Article Article 1-5', 'Taxable Assets', 'Tax Law'),
  ('LBN-TAX-004', 'Article 1-5', 'Biens imposables - tous les biens meubles et immeubles situés au Liban', 'fr', 'Legislative Decree on Inheritance and Gift Tax, Article Article 1-5', 'Taxable Assets', 'Tax Law'),
  ('LBN-TAX-004', 'Article 1-5', 'الأصول الخاضعة للضريبة - جميع الأموال المنقولة وغير المنقولة الواقعة في لبنان', 'ar', 'Legislative Decree on Inheritance and Gift Tax, Article Article 1-5', 'Taxable Assets', 'Tax Law'),
  ('LBN-TAX-004', 'Article 10-15', 'Deductions for debts, funeral expenses, and specific exemptions based on relationship', 'en', 'Legislative Decree on Inheritance and Gift Tax, Article Article 10-15', 'Deductions and Exemptions', 'Tax Law'),
  ('LBN-TAX-004', 'Article 10-15', 'Exemptions - dettes et frais funéraires', 'fr', 'Legislative Decree on Inheritance and Gift Tax, Article Article 10-15', 'Deductions and Exemptions', 'Tax Law'),
  ('LBN-TAX-004', 'Article 10-15', 'الإعفاءات - الديون ومصاريف الجنازة', 'ar', 'Legislative Decree on Inheritance and Gift Tax, Article Article 10-15', 'Deductions and Exemptions', 'Tax Law'),
  ('LBN-TAX-004', 'Tax Rates', 'Progressive rates from 3% to 45% based on relationship to deceased and amount transferred', 'en', 'Legislative Decree on Inheritance and Gift Tax, Article Tax Rates', 'Tax Rates', 'Tax Law'),
  ('LBN-TAX-004', 'Tax Rates', 'Taux progressifs de 3% à 45% selon le degré de parenté', 'fr', 'Legislative Decree on Inheritance and Gift Tax, Article Tax Rates', 'Tax Rates', 'Tax Law'),
  ('LBN-TAX-004', 'Tax Rates', 'معدلات تصاعدية من 3% إلى 45% حسب درجة القرابة', 'ar', 'Legislative Decree on Inheritance and Gift Tax, Article Tax Rates', 'Tax Rates', 'Tax Law'),
  ('LBN-TAX-004', NULL, 'The Inheritance and Gift Tax Law of 1959 establishes the framework for taxing transfers of wealth upon death or by gift. The tax applies based on both territoriality and residence principles. The progressive rate structure favors close family members with lower rates.', 'en', 'Legislative Decree on Inheritance and Gift Tax — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-005', 'Article 1-2', 'Customs provisions consolidated into single law; customs duties set by Higher Council of Customs', 'en', 'Customs Law, Article Article 1-2', 'General Provisions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 1-2', 'Les dispositions douanières sont regroupées en une loi unique', 'fr', 'Customs Law, Article Article 1-2', 'General Provisions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 1-2', 'تجمع أحكام الجمارك في قانون موحد', 'ar', 'Customs Law, Article Article 1-2', 'General Provisions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 8-9', 'Customs tariffs include ordinary and preferential tariffs; minimum 5% duty on imports', 'en', 'Customs Law, Article Article 8-9', 'Tariff Structure', 'Tax Law'),
  ('LBN-TAX-005', 'Article 8-9', 'Tarifs douaniers - ordinaires et préférentiels', 'fr', 'Customs Law, Article Article 8-9', 'Tariff Structure', 'Tax Law'),
  ('LBN-TAX-005', 'Article 8-9', 'التعريفة الجمركية - العادية والمفضلة', 'ar', 'Customs Law, Article Article 8-9', 'Tariff Structure', 'Tax Law'),
  ('LBN-TAX-005', 'Article 295', 'Goods imported for President of Republic, public administrations, grants, and international agreements may be exempt', 'en', 'Customs Law, Article Article 295', 'Exemptions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 295', 'Exemptions et privilèges', 'fr', 'Customs Law, Article Article 295', 'Exemptions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 295', 'الإعفاءات والامتيازات', 'ar', 'Customs Law, Article Article 295', 'Exemptions', 'Tax Law'),
  ('LBN-TAX-005', 'Article 358', 'Penalties for customs violations including smuggling and false declarations', 'en', 'Customs Law, Article Article 358', 'Penalties', 'Tax Law'),
  ('LBN-TAX-005', 'Article 358', 'Pénalités pour infractions douanières', 'fr', 'Customs Law, Article Article 358', 'Penalties', 'Tax Law'),
  ('LBN-TAX-005', 'Article 358', 'عقوبات المخالفات الجمركية', 'ar', 'Customs Law, Article Article 358', 'Penalties', 'Tax Law'),
  ('LBN-TAX-005', NULL, 'Lebanon''s Customs Law governs import and export duties. The law establishes the Higher Council of Customs which sets tariff rates. Lebanon applies the Harmonized System for tariff classification.', 'en', 'Customs Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-006', 'Proportionate Stamp Duty', 'Proportionate stamp duty of 0.4% on all deeds and contracts mentioning specific payments', 'en', 'Stamp Duty Law, Article Proportionate Stamp Duty', 'Proportionate Stamp Duty', 'Tax Law'),
  ('LBN-TAX-006', 'Proportionate Stamp Duty', 'Timbre proportionnel de 0.4% sur les contrats et actes', 'fr', 'Stamp Duty Law, Article Proportionate Stamp Duty', 'Proportionate Stamp Duty', 'Tax Law'),
