  ('LBN-TAX-006', 'Fixed Stamp Duty', 'Fixed stamp duty ranging from LL 1,000 to LL 2 million on documents per schedules', 'en', 'Stamp Duty Law, Article Fixed Stamp Duty', 'Fixed Stamp Duty', 'Tax Law'),
