INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-TAX-007', 'Law 296', 'Faciliter l''investissement étranger et réduire les frais d''enregistrement', 'fr', 'Real Estate Registration and Transfer Tax Law, Article Law 296', 'Foreign Ownership Rules', 'Tax Law'),
  ('LBN-TAX-007', 'Law 296', 'تسهيل الاستثمار الأجنبي وتقليل رسوم تسجيل العقارات', 'ar', 'Real Estate Registration and Transfer Tax Law, Article Law 296', 'Foreign Ownership Rules', 'Tax Law'),
  ('LBN-TAX-007', 'Law 360', 'Foreigners can acquire 3% of total Lebanon area (up to 10% in Beirut); 3,000m2 without Council of Ministers decree', 'en', 'Real Estate Registration and Transfer Tax Law, Article Law 360', 'Foreign Acquisition Limits', 'Tax Law'),
  ('LBN-TAX-007', 'Law 360', 'Permettre aux étrangers d''acquérir 3% de la superficie totale du Liban', 'fr', 'Real Estate Registration and Transfer Tax Law, Article Law 360', 'Foreign Acquisition Limits', 'Tax Law'),
  ('LBN-TAX-007', 'Law 360', 'السماح للأجانب بشراء 3% من مساحة لبنان الكلية', 'ar', 'Real Estate Registration and Transfer Tax Law, Article Law 360', 'Foreign Acquisition Limits', 'Tax Law'),
