  ('LBN-TAX-008', 'General Provisions', 'Excise taxes apply to alcoholic beverages, tobacco products, gasoline, and vehicles', 'en', 'Excise Taxes, Article General Provisions', 'Taxable Products', 'Tax Law'),
  ('LBN-TAX-008', 'General Provisions', 'Taxes d''accise sur les boissons alcoolisées, le tabac et les carburants', 'fr', 'Excise Taxes, Article General Provisions', 'Taxable Products', 'Tax Law'),
  ('LBN-TAX-008', 'General Provisions', 'الضرائب الانتقائية على المشروبات الكحولية والتبغ والوقود', 'ar', 'Excise Taxes, Article General Provisions', 'Taxable Products', 'Tax Law'),
  ('LBN-TAX-008', NULL, 'Excise taxes in Lebanon are primarily applied to ''sin goods'' and luxury items. Rates are adjusted annually through Budget Laws.', 'en', 'Excise Taxes — Historical Context', 'Historical context and overview', 'Tax Law'),
