  ('LBN-TAX-009', 'Movable Capital WHT', '10% WHT on income from movable capital including dividends, interest, directors'' fees', 'en', 'Withholding Tax Regulations, Article Movable Capital WHT', 'Movable Capital Tax', 'Tax Law'),
  ('LBN-TAX-009', 'Movable Capital WHT', 'Retenue sur capitaux mobiliers de 10%', 'fr', 'Withholding Tax Regulations, Article Movable Capital WHT', 'Movable Capital Tax', 'Tax Law'),
