  ('LBN-TAX-009', 'Non-Resident WHT', 'Non-residents subject to 3.4% WHT on goods and 8.5% on services (as of Q2 2024)', 'en', 'Withholding Tax Regulations, Article Non-Resident WHT', 'Non-Resident Withholding Tax', 'Tax Law'),
  ('LBN-TAX-009', 'Non-Resident WHT', 'Retenue non-résidents 3.4% sur marchandises et 8.5% sur services', 'fr', 'Withholding Tax Regulations, Article Non-Resident WHT', 'Non-Resident Withholding Tax', 'Tax Law'),
