  ('LBN-TAX-009', NULL, 'Withholding taxes are a key mechanism for revenue collection in Lebanon. The 2024 amendments increased non-resident WHT rates significantly to boost revenue.', 'en', 'Withholding Tax Regulations — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-010', 'Filing Deadlines', 'Corporate income tax return due before February of following year; VAT quarterly by 20th of following month', 'en', 'Tax Procedures and Control Law, Article Filing Deadlines', 'Filing Deadlines', 'Tax Law'),
  ('LBN-TAX-010', 'Filing Deadlines', 'Délais de déclaration des impôts', 'fr', 'Tax Procedures and Control Law, Article Filing Deadlines', 'Filing Deadlines', 'Tax Law'),
  ('LBN-TAX-010', 'Filing Deadlines', 'المواعيد النهائية لتقديم الإقرارات الضريبية', 'ar', 'Tax Procedures and Control Law, Article Filing Deadlines', 'Filing Deadlines', 'Tax Law'),
  ('LBN-TAX-010', 'Tax Audit', 'Tax authorities have broad powers to audit and verify tax declarations; field visits and comparison with similar transactions', 'en', 'Tax Procedures and Control Law, Article Tax Audit', 'Tax Audit Powers', 'Tax Law'),
  ('LBN-TAX-010', 'Tax Audit', 'Contrôle fiscal et vérification', 'fr', 'Tax Procedures and Control Law, Article Tax Audit', 'Tax Audit Powers', 'Tax Law'),
  ('LBN-TAX-010', 'Tax Audit', 'المراقبة الضريبية والتحقق', 'ar', 'Tax Procedures and Control Law, Article Tax Audit', 'Tax Audit Powers', 'Tax Law'),
  ('LBN-TAX-010', 'Penalties', 'Penalties for late filing, non-payment, and tax evasion; general reduction of fines under 2024 amendments', 'en', 'Tax Procedures and Control Law, Article Penalties', 'Penalties', 'Tax Law'),
