  ('LBN-TAX-010', 'Penalties', 'الغرامات والعقوبات الضريبية', 'ar', 'Tax Procedures and Control Law, Article Penalties', 'Penalties', 'Tax Law'),
  ('LBN-TAX-010', NULL, 'Tax procedures in Lebanon are governed by various provisions scattered across tax laws. Recent reforms have focused on electronic filing and streamlining compliance.', 'en', 'Tax Procedures and Control Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-011', 'General Provisions', 'Tax amnesty laws allow delinquent taxpayers to settle their tax obligations with reduced penalties', 'en', 'Tax Amnesty and Settlement Laws, Article General Provisions', 'Amnesty Provisions', 'Tax Law'),
  ('LBN-TAX-011', 'General Provisions', 'Les lois d''amnistie fiscale permettent aux contribuables en retard de régulariser leur situation', 'fr', 'Tax Amnesty and Settlement Laws, Article General Provisions', 'Amnesty Provisions', 'Tax Law'),
  ('LBN-TAX-011', 'General Provisions', 'قوانين العفو الضريبي تسمح للمقصرين بتسوية وضعهم الضريبي', 'ar', 'Tax Amnesty and Settlement Laws, Article General Provisions', 'Amnesty Provisions', 'Tax Law'),
  ('LBN-TAX-011', NULL, 'Lebanon has periodically enacted tax amnesty laws to encourage compliance and increase revenue collection. These laws typically offer reduced penalties and interest for taxpayers who voluntarily disclose and pay outstanding taxes.', 'en', 'Tax Amnesty and Settlement Laws — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-012', 'General', 'Avoid double taxation on income and profits; typically reduce WHT rates on dividends, interest, and royalties', 'en', 'Double Taxation Treaties, Article General', 'Purpose of DTTs', 'Tax Law'),
  ('LBN-TAX-012', 'General', 'Éviter la double imposition sur les revenus et les bénéfices', 'fr', 'Double Taxation Treaties, Article General', 'Purpose of DTTs', 'Tax Law'),
  ('LBN-TAX-012', 'General', 'تجنب الازدواج الضريبي على الدخل والأرباح', 'ar', 'Double Taxation Treaties, Article General', 'Purpose of DTTs', 'Tax Law'),
  ('LBN-TAX-012', NULL, 'Lebanon has concluded over 30 double taxation treaties to promote international trade and investment. These treaties generally follow the OECD model and reduce withholding tax rates on cross-border payments.', 'en', 'Double Taxation Treaties — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-013', 'Business Objectives', 'Holding companies restricted to: owning shares in Lebanese/foreign companies; managing owned companies; lending to subsidiaries; owning patents/trademarks; owning properties for business requirements', 'en', 'Holding Companies Law, Article Business Objectives', 'Permitted Activities', 'Tax Law'),
  ('LBN-TAX-013', 'Business Objectives', 'Objectifs commerciaux limités des sociétés de participations', 'fr', 'Holding Companies Law, Article Business Objectives', 'Permitted Activities', 'Tax Law'),
  ('LBN-TAX-013', 'Business Objectives', 'الأهداف المحدودة للشركات القابضة', 'ar', 'Holding Companies Law, Article Business Objectives', 'Permitted Activities', 'Tax Law'),
  ('LBN-TAX-013', 'Tax Exemptions', 'Exempt from corporate income tax and dividend WHT; subject to tax on capital and reserves capped at LBP 50 million annually', 'en', 'Holding Companies Law, Article Tax Exemptions', 'Tax Treatment', 'Tax Law'),
  ('LBN-TAX-013', 'Tax Exemptions', 'Exemptions fiscales pour les sociétés de participations', 'fr', 'Holding Companies Law, Article Tax Exemptions', 'Tax Treatment', 'Tax Law'),
  ('LBN-TAX-013', 'Tax Exemptions', 'إعفاءات ضريبية للشركات القابضة', 'ar', 'Holding Companies Law, Article Tax Exemptions', 'Tax Treatment', 'Tax Law'),
  ('LBN-TAX-013', NULL, 'The Holding Companies Law was enacted in 1983 to encourage investment and regional headquarters in Lebanon. It provides significant tax exemptions to companies whose main activity is owning shares in other companies.', 'en', 'Holding Companies Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-014', 'Business Objectives', 'Offshore companies limited to trade and activities strictly outside Lebanese territories', 'en', 'Offshore Companies Law, Article Business Objectives', 'Permitted Activities', 'Tax Law'),
  ('LBN-TAX-014', 'Business Objectives', 'Activités limitées des sociétés offshore', 'fr', 'Offshore Companies Law, Article Business Objectives', 'Permitted Activities', 'Tax Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
