  ('LBN-TAX-015', 'Fixed Assets', 'Capital gains from disposal of fixed assets subject to 15% tax; companies can revalue every 5 years (annually until 2026 for lump-sum taxpayers)', 'en', 'Capital Gains Tax Provisions, Article Fixed Assets', 'Fixed Assets Capital Gains', 'Tax Law'),
