  ('LBN-TAX-015', 'Shares', 'Gains from sale of shares: 15% if non-current assets; 17% CIT for investment companies; 10% movable capital tax for non-residents', 'en', 'Capital Gains Tax Provisions, Article Shares', 'Shares Capital Gains', 'Tax Law'),
