  ('LBN-TAX-016', 'Employer Contributions', 'Employer contributions: 8% maternity/sickness (max LBP 18M/month), 6% family (max LBP 12M/month), 8.5% end of service (no ceiling)', 'en', 'Social Security Law, Article Employer Contributions', 'Employer Contributions', 'Tax Law'),
