  ('LBN-TAX-018', NULL, 'The 2025 Budget was submitted to government in September 2024 with a projected deficit. It introduces new fees and modifies tax calculation methods for foreign currency salaries.', 'en', 'Budget Law 2025 (Draft) — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-019', 'Applicable Entities', 'Applies to: insurance companies, transport companies, oil refineries, public work contractors', 'en', 'Deemed Profit Method Provisions, Article Applicable Entities', 'Scope', 'Tax Law'),
