  ('LBN-TAX-020', 'Municipal Tax on Rents', 'Taxe municipale sur les revenus locatifs', 'fr', 'Municipal Tax Provisions, Article Municipal Tax on Rents', 'Municipal Tax on Rents', 'Tax Law'),
